            int first = random.nextInt(10) + 1;
            int second = random.nextInt(10) + 1;
            System.out.printf("Question %d: %d + %d = ?%n", round, first, second);
            int answer = scanner.nextInt();
            int correct = add(first, second);
            if (answer == correct) {
                System.out.println("Correct");
                score++;
            } else {
                System.out.println("Incorrect: " + correct);
            }
        }
        System.out.println("Score: " + score + "/3");
    }

    public static int add(int a, int b) {
        return a + b;
    }
}
